                _db.Context.SaveChanges();

            }
        }
    }

    List<EntityInfo> savedJobEntities;
    if (saveMap.TryGetValue(typeof(Job), out savedJobEntities))
    {
        foreach (var savedJobEntity in savedJobEntities)
        {
            var savedJob = savedJobEntity.Entity as Job;
            if (savedJob == null)
            {
                continue;
            }

            bool? oldFinishedValue = null;
            object obj;
            if (savedJobEntity.OriginalValuesMap.TryGetValue(nameof(Job.Finished), out obj))
            {
                oldFinishedValue = obj as bool?;
            }
            else
            {
                //if Finished field was not changed we do nothing
                continue;
            }

            //job was moved into the finished state;
            if (savedJob.Finished.FullValue() && !oldFinishedValue.FullValue())
            {
                var nextScheduler = new NextStageJobScheduler(_db.Context);
                var newJob = nextScheduler.SheduleNext(savedJob);
                if (newJob != null)
                {
                    _db.Context.Jobs.Add(newJob);
                    _db.Context.SaveChanges();
                }
            }

        }
    }

    //DO NOTHING
}

